from bol_reference_parser import ParsedReference, RawReferenceSet, parse_bol_references


def test_prefixed_bol_token_normalizes_punctuation_and_zeroes():
    raw = RawReferenceSet(references=("bol-00012345",))
    assert parse_bol_references(raw) == (ParsedReference("BOL", "12345"),)


def test_bare_numeric_token_in_bol_length_window_becomes_bol():
    raw = RawReferenceSet(references=("  00123456  ",))
    assert parse_bol_references(raw) == (ParsedReference("BOL", "123456"),)


def test_long_numeric_payload_keeps_last_twelve_digits():
    raw = RawReferenceSet(references=("SO123456789012345",))
    assert parse_bol_references(raw) == (ParsedReference("SO", "456789012345"),)


def test_long_alphanumeric_payload_is_rejected():
    raw = RawReferenceSet(references=("PO-ABC1234567890",))
    assert parse_bol_references(raw) == ()


def test_label_without_following_value_produces_nothing():
    raw = RawReferenceSet(references=("pickup",))
    assert parse_bol_references(raw) == ()


def test_zero_pickup_reference_is_not_lifted_to_one():
    raw = RawReferenceSet(references=("PO-09", "BOL-09", "PU-0"))
    assert parse_bol_references(raw) == (
        ParsedReference("PO", "9"),
        ParsedReference("PU", "0"),
    )


def test_all_zero_payload_keeps_zero_for_short_prefixes():
    raw = RawReferenceSet(references=("PU-000", "PO-00"))
    assert parse_bol_references(raw) == (
        ParsedReference("PU", "0"),
        ParsedReference("PO", "0"),
    )


def test_order_is_preserved_across_multiple_reference_types():
    raw = RawReferenceSet(references=("PO-22", "SO 000777", "987654"))
    assert parse_bol_references(raw) == (
        ParsedReference("PO", "22"),
        ParsedReference("SO", "777"),
        ParsedReference("BOL", "987654"),
    )

edi_210_charge_mapping.py:
"""Normalize EDI 210 freight invoice line items into invoice charge categories.

Business rules:
- Carriers send line items with an EDI accessorial code, a free-text description, and an amount.
- Negative amounts are treated as credits and map to the ``credit`` category regardless of code.
- Zero-dollar lines map to ``ignore`` because they do not affect settlement.
- The line-haul code ``400`` normally maps to ``linehaul`` but maps to ``fuel`` when the
  description clearly says fuel surcharge.
- Known accessorial codes map directly: ``405`` and ``FSC`` to fuel, ``DET`` and ``DLY`` to
  detention, ``LUM`` and ``HND`` to lumper, ``TON`` to overweight, ``STP`` to stopoff,
  ``LAY`` to layover, ``BOR`` to border, and ``MSC`` to misc.
- Description keywords can override an unknown or generic code. Description matching is case-
  insensitive and checks practical phrases used by billing teams.
- Blank (uncoded) lines with small positive amounts under $25.00 default to ``misc``; blank
  lines with amounts from $25.00 and up default to ``other``.
- Unknown nonblank codes (for example ``ABC``) are not treated as uncoded: they map to the
  generic ``other`` bucket regardless of amount. The generic code ``999`` behaves this way too,
  except that clear fuel, detention, and lumper description phrases still override it.
- If both code and description suggest different non-credit categories, the description wins only
  for clear fuel, detention, and lumper phrases; otherwise the explicit code wins.
- Amounts are rounded to cents with half-up rounding before threshold checks.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
SMALL_MISC_LIMIT = Decimal("25.00")


@dataclass(frozen=True)
class EDI210ChargeLine:
    amount: Decimal
    code: str | None = None
    description: str = ""


@dataclass(frozen=True)
class MappedCharge:
    category: str
    normalized_amount: Decimal
    source: str


def _normalize_amount(amount: Decimal) -> Decimal:
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def _clean_code(code: str | None) -> str:
    if code is None:
        return ""
    return code.strip().upper()


def _clean_text(text: str) -> str:
    return " ".join(text.strip().lower().split())


def _category_from_description(text: str) -> str | None:
    if not text:
        return None
    if "fuel surcharge" in text or text == "fuel" or text.startswith("fsc"):
        return "fuel"
    if "detention" in text or "delay time" in text or "driver delay" in text:
        return "detention"
    if "lumper" in text or "unloading" in text or "loading assist" in text:
        return "lumper"
    if "line haul" in text or "linehaul" in text or text == "freight":
        return "linehaul"
    if "stop off" in text or "stopoff" in text:
        return "stopoff"
    return None


def _category_from_code(code: str) -> str | None:
    code_map = {
        "400": "linehaul",
        "405": "fuel",
        "FSC": "fuel",
        "DET": "detention",
        "DLY": "detention",
        "LUM": "lumper",
        "HND": "lumper",
        "TON": "overweight",
        "STP": "stopoff",
        "LAY": "layover",
        "BOR": "border",
        "MSC": "misc",
    }
    return code_map.get(code)


def _fallback_category(amount: Decimal) -> str:
    if amount < SMALL_MISC_LIMIT:
        return "misc"
    return "other"


def map_edi_210_charges(line: EDI210ChargeLine) -> MappedCharge:
    """Map one EDI 210 charge line to a normalized invoice category.

    Returns the chosen category, the rounded amount, and a short source marker showing
    which rule decided the mapping.
    """
    amount = _normalize_amount(line.amount)
    if amount < Decimal("0.00"):
        return MappedCharge("credit", amount, "amount")
    if amount == Decimal("0.00"):
        return MappedCharge("ignore", amount, "amount")

    code = _clean_code(line.code)
    text = _clean_text(line.description)
    desc_category = _category_from_description(text)
    code_category = _category_from_code(code)

    if code == "400" and desc_category == "fuel":
        return MappedCharge("fuel", amount, "description")

    if desc_category in {"fuel", "detention", "lumper"}:
        if code_category is None or code_category == "misc" or code == "999":
            return MappedCharge(desc_category, amount, "description")

    if code_category is not None:
        return MappedCharge(code_category, amount, "code")

    if desc_category is not None:
        return MappedCharge(desc_category, amount, "description")

    if code == "":
        # Truly uncoded lines use the amount threshold: small amounts are misc,
        # larger amounts are other.
        return MappedCharge(_fallback_category(amount), amount, "fallback")

    # Unknown nonblank codes, including the generic 999, map to other regardless
    # of amount. Only blank codes use the amount-threshold fallback.
    return MappedCharge("other", amount, "fallback")

billing_weight.py:
"""Billable weight for LTL shipments.

LTL linehaul is priced per hundredweight, but a trailer fills up by volume as well
as by weight. Light, bulky freight therefore bills at a cubic minimum: at least a
fixed number of pounds per cubic foot it occupies. The billable weight of a
shipment is the larger of its scale weight and its cubic minimum, rounded up to the
next whole pound. Rating calls ``billable_weight`` for every LTL shipment.
"""

import math
from dataclasses import dataclass
from decimal import Decimal

CUBIC_MINIMUM_LB_PER_FT3 = Decimal("6")
CUBIC_INCHES_PER_FOOT = Decimal("1728")


@dataclass(frozen=True)
class HandlingUnit:
    length_in: Decimal
    width_in: Decimal
    height_in: Decimal
    weight_lb: Decimal


@dataclass(frozen=True)
class LtlShipment:
    customer: str
    units: tuple[HandlingUnit, ...]


def cubic_feet(unit: HandlingUnit) -> Decimal:
    if min(unit.length_in, unit.width_in, unit.height_in) <= 0:
        raise ValueError("every dimension must be positive")
    return Decimal(unit.length_in) * Decimal(unit.width_in) * Decimal(unit.height_in) / CUBIC_INCHES_PER_FOOT


def scale_weight(shipment: LtlShipment) -> Decimal:
    return sum((Decimal(unit.weight_lb) for unit in shipment.units), Decimal("0"))


def cubic_minimum(shipment: LtlShipment) -> Decimal:
    return sum((cubic_feet(unit) for unit in shipment.units), Decimal("0")) * CUBIC_MINIMUM_LB_PER_FT3


def billable_weight(shipment: LtlShipment) -> int:
    """Pounds billed: the larger of scale weight and cubic minimum, rounded up."""
    if not shipment.units:
        raise ValueError("shipment has no handling units")
    return math.ceil(max(scale_weight(shipment), cubic_minimum(shipment)))

